const config = $('Set Config').first().json;
const raw = $input.first().json.data || $input.first().json.body || '';
const match = String(raw).match(/(?:const|let|var)\s+CQR_DATA\s*=\s*([\s\S]*?)\s*;?\s*$/);
if (!match) {
  throw new Error('Cannot parse CQR_DATA from dashboard data file');
}
const data = JSON.parse(match[1]);
const periodKey = config.periodKey;
const minRegisterSample = Number(config.minRegisterSample || 30);
const d14WarningThreshold = Number(config.d14WarningThreshold || 15);
const rows = data.channel_data[`ALL|${periodKey}`] || [];
const overview = data.overview_data[`ALL|${periodKey}`] || {};
const totalRetention = data.total_user_retention[`ALL|${periodKey}`] || {};
const mau = data.total_mau[`ALL|${periodKey}`] || null;
const usableRows = rows.filter(row => row.register >= minRegisterSample && row.d14 !== null && row.d14 !== undefined);
const sortedByD14 = [...usableRows].sort((a, b) => b.d14 - a.d14);
const best = sortedByD14[0] || null;
const weakest = sortedByD14[sortedByD14.length - 1] || null;
const warnings = [];
for (const row of usableRows) {
  if (row.d14 < d14WarningThreshold) {
    warnings.push(`${row.channel}: D14 ${row.d14}% ต่ำกว่า threshold ${d14WarningThreshold}%`);
  }
  if (row.d1 < 20) {
    warnings.push(`${row.channel}: D1 ${row.d1}% ต่ำ อาจมีปัญหา install/login flow`);
  }
}
if (!rows.length) warnings.push(`ไม่พบ channel_data สำหรับ ALL|${periodKey}`);
if (!overview.new_register) warnings.push('Overview data ไม่ครบหรือ Register เป็น 0');
if (!totalRetention.has_login) warnings.push('Total User Retention ยังไม่มี login data ครบ');
return [{
  json: {
    periodKey,
    dashboardUrl: config.dashboardUrl,
    newRegister: overview.new_register || 0,
    paidRegister: overview.paid_register || 0,
    d1: overview.d1,
    d3: overview.d3,
    d7: overview.d7,
    d14: overview.d14,
    mau,
    bestChannel: best ? best.channel : '-',
    bestD14: best ? best.d14 : null,
    weakestChannel: weakest ? weakest.channel : '-',
    weakestD14: weakest ? weakest.d14 : null,
    totalRetentionD14: totalRetention.d14,
    totalRetentionD30: totalRetention.d30,
    warnings,
    status: warnings.length ? 'WARNING' : 'OK'
  }
}];

const item = $input.first().json;
const warningText = item.warnings.length ? item.warnings.map((w, i) => `${i + 1}. ${w}`).join('
') : 'ไม่พบ warning สำคัญ';
const d30Text = item.totalRetentionD30 === null || item.totalRetentionD30 === undefined ? 'รอ buffer D30' : `${item.totalRetentionD30}%`;
const message = `CQR Weekly Alert | ${item.periodKey}

Status: ${item.status}
Register: ${Number(item.newRegister).toLocaleString()}
Paid Register: ${Number(item.paidRegister).toLocaleString()}
New User Retention: D1 ${item.d1}% | D3 ${item.d3}% | D7 ${item.d7}% | D14 ${item.d14}%
Total User Retention: D14 ${item.totalRetentionD14 ?? '-'}% | D30 ${d30Text}
MAU: ${item.mau ? Number(item.mau).toLocaleString() : '-'}

Best Channel: ${item.bestChannel} (${item.bestD14 ?? '-'}% D14)
Weakest Channel: ${item.weakestChannel} (${item.weakestD14 ?? '-'}% D14)

Warnings:
${warningText}

Dashboard: ${item.dashboardUrl}`;
return [{ json: { ...item, alertMessage: message } }];
